L000017	\begin{document}
L000018	\title{Competing states in the $S=1/2$ triangular-lattice $J_1$-$J_2$ Heisenberg model: a dynamical density-matrix renormalization group study}
L000019	
L000020	\begin{CJK*}{UTF8}{}
L000021	\author{Shengtao Jiang (\CJKfamily{gbsn}蒋晟韬)}
L000022	\altaffiliation{contact author: stjiang@stanford.edu}
L000023	\affiliation{Stanford Institute for Materials and Energy Sciences, SLAC National Accelerator Laboratory and Stanford University, Menlo Park, CA 94025, USA}
